import json
import re
from pathlib import Path

# Load locked sets
with open('/home/giak/aidd-device-work-rejeu3/2026-10-24-055310-shadow-areas-design/framework-origin/plugins/aidd-refine/skills/03-shadow-areas/references/locked-sets.json') as f:
